templates.buildGradle:
buildscript {
	repositories {
		maven { url = 'https://maven.minecraftforge.net/' }
		mavenCentral()
	}
	dependencies {
		classpath 'net.minecraftforge.gradle:ForgeGradle:{{gradle_forgeGradleVersion}}'
	}
}
apply plugin: 'net.minecraftforge.gradle'
apply plugin: 'eclipse'
apply plugin: 'maven-publish'

version = '{{modVersion}}'
group = '{{packageName}}'
archivesBaseName = '{{modId}}'

sourceCompatibility = targetCompatibility = compileJava.sourceCompatibility = compileJava.targetCompatibility = '{{javaVersion}}'

minecraft {
	mappings channel: '{{gradle_mappingChannel}}', version: '{{gradle_mappingVersion}}'

	runs {
		client {
			workingDirectory project.file('run')
			property 'forge.logging.markers', 'SCAN,REGISTRIES,REGISTRYDUMP'
			property 'forge.logging.console.level', 'debug'
		}
		server {
			workingDirectory project.file('run')
			property 'forge.logging.markers', 'SCAN,REGISTRIES,REGISTRYDUMP'
			property 'forge.logging.console.level', 'debug'
		}
	}
}

dependencies {
	minecraft 'net.minecraftforge:forge:{{mcVersion}}-{{gradle_forgeVersion}}'
}

jar {
	manifest {
		attributes(
				'Specification-Title': '{{modId}}',
				'Specification-Vendor': '{{authors}}',
				'Specification-Version': '1',
				'Implementation-Title': project.name,
				'Implementation-Version': project.version,
				'Implementation-Vendor': '{{authors}}',
		)
	}
}

templates.gradleProps:
# Gradle (this target needs a Java 8 daemon; Gradle 4.10.3 does not start on Java 9+)
org.gradle.jvmargs=-Xmx2G
org.gradle.parallel=true

# Forge properties (https://files.minecraftforge.net/net/minecraftforge/forge/)
minecraft_version={{mcVersion}}
forge_version={{gradle_forgeVersion}}
mapping_channel={{gradle_mappingChannel}}
mapping_version={{gradle_mappingVersion}}

# Mod properties
mod_id={{modId}}
mod_name={{modName}}
mod_license={{license}}
mod_version={{modVersion}}
mod_group_id={{packageName}}
mod_authors={{authors}}
mod_description={{description}}

