package {{packageName}};

import net.minecraft.util.ResourceLocation;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.event.FMLPreInitializationEvent;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

/** Entry point of {{modName}} (generated by mcmodkit). */
@Mod(modid = {{mainClassSimpleName}}.MOD_ID, name = "{{modName}}", version = "{{modVersion}}",
		acceptedMinecraftVersions = "[{{mcVersion}}]")
public class {{mainClassSimpleName}} {

	public static final String MOD_ID = "{{modId}}";
	public static final Logger LOGGER = LogManager.getLogger(MOD_ID);

	@Mod.EventHandler
	public void preInit(FMLPreInitializationEvent event) {
		{{mainClassSimpleName}}Items.init();
		{{mainClassSimpleName}}Blocks.init();
{{REGISTRY_INIT_CALLS}}
		LOGGER.info("{} loaded", MOD_ID);
	}

	public static ResourceLocation id(String path) {
		return new ResourceLocation(MOD_ID, path);
	}
}

