import net.minecraftforge.fml.relauncher.Side;
import net.minecraftforge.fml.relauncher.SideOnly;
{{ITEM_BEHAVIOR_IMPORTS}}

/** Items and creative tab of {{modName}} (generated by mcmodkit). */
@Mod.EventBusSubscriber(modid = {{mainClassSimpleName}}.MOD_ID)
public final class {{mainClassSimpleName}}Items {

	/** Items shown in this mod's own tab; also the icon source. */
	private static final List<Item> TAB_ENTRIES = new ArrayList<>();
	/** Everything this mod registers, in registration order. */
	private static final List<Item> REGISTRY = new ArrayList<>();

	public static final CreativeTabs TAB = new CreativeTabs("{{namespace}}") {
		@Override
		@SideOnly(Side.CLIENT)
		public ItemStack getTabIconItem() {
			return TAB_ENTRIES.isEmpty() ? new ItemStack(Blocks.STONE) : new ItemStack(TAB_ENTRIES.get(0));
		}
	};

{{ITEM_REGISTRATIONS}}

	private {{mainClassSimpleName}}Items() {
	}

	public static void init() {
{{TAB_BLOCK}}
{{ITEM_GROUP_HOOKS}}
	}

	/** Puts an item in this mod's tab. Called from init(), which runs before the game reads tabs. */
	public static void addToModTab(Item item) {
		TAB_ENTRIES.add(item);
		item.setCreativeTab(TAB);
	}

	@SubscribeEvent
	public static void onRegisterItems(RegistryEvent.Register<Item> event) {
		for (Item item : REGISTRY) {
			event.getRegistry().register(item);
		}
	}

	private static Item register(String name, Item item) {
		item.setRegistryName({{mainClassSimpleName}}.MOD_ID, name);
		item.setUnlocalizedName({{mainClassSimpleName}}.MOD_ID + "." + name);
		REGISTRY.add(item);
		return item;
	}
}

templates.blocksRegistryClass:
package {{packageName}};

import java.util.ArrayList;
import java.util.List;

import net.minecraft.block.Block;
import net.minecraft.block.material.Material;
import net.minecraft.item.Item;
import net.minecraft.item.ItemBlock;
import net.minecraftforge.event.RegistryEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.fml.common.eventhandler.SubscribeEvent;

/** Blocks of {{modName}} (generated by mcmodkit). Each block also gets a matching ItemBlock. */
@Mod.EventBusSubscriber(modid = {{mainClassSimpleName}}.MOD_ID)
public final class {{mainClassSimpleName}}Blocks {

	private static final List<Block> REGISTRY = new ArrayList<>();
	private static final List<Item> BLOCK_ITEMS = new ArrayList<>();

{{BLOCK_REGISTRATIONS}}

	private {{mainClassSimpleName}}Blocks() {
	}

	public static void init() {
	}

	@SubscribeEvent
	public static void onRegisterBlocks(RegistryEvent.Register<Block> event) {
		for (Block block : REGISTRY) {
			event.getRegistry().register(block);
		}
	}

	@SubscribeEvent
	public static void onRegisterBlockItems(RegistryEvent.Register<Item> event) {
		for (Item item : BLOCK_ITEMS) {
			event.getRegistry().register(item);
		}
	}

	static Block register(String name, Block block, String tool) {
		block.setRegistryName({{mainClassSimpleName}}.MOD_ID, name);
		block.setUnlocalizedName({{mainClassSimpleName}}.MOD_ID + "." + name);
		if (!"none".equals(tool)) {
			// Replaces the 1.13+ mineable block tag. Level 1 is the era's default for a plain block;
			// the ModSpec models the tool, not the tier.
			block.setHarvestLevel(tool, 1);
		}
		REGISTRY.add(block);
		return block;
	}

	static Item registerItem(Block block) {
		ItemBlock item = new ItemBlock(block);
		item.setRegistryName(block.getRegistryName());
		BLOCK_ITEMS.add(item);
		return item;
	}
}
